def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_bids = []
    rich_threat = False

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= DAILY_SALARY * 2 or opp.get('hp', 0) > 4:
                    threat_bids.append(float(bid))
            if opp.get('budget', 0) > 250 and opp.get('hp', 0) > 2:
                rich_threat = True

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.18))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat_prev = max(threat_bids) if threat_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 0.75
    elif hp <= 4:
        danger += 0.4
    if no_water_days >= 2:
        danger += 0.7
    elif no_water_days == 1:
        danger += 0.3

    if supply >= 23:
        base = DAILY_SALARY * 0.26
    elif supply >= 20:
        base = DAILY_SALARY * 0.38
    elif supply >= 17:
        base = DAILY_SALARY * 0.52
    else:
        base = DAILY_SALARY * 0.68

    if highest_threat_prev > 0:
        if danger >= 0.9:
            target = max(base + DAILY_SALARY * 0.18, highest_threat_prev + 3.0)
        elif scarcity > 0.6:
            target = max(base, highest_threat_prev + 1.5)
        else:
            target = max(base, highest_threat_prev * 0.72)
    else:
        target = base

    if rich_threat and supply <= 18:
        target += 6.0

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif hp <= 4 and supply <= 17:
        target = max(target, DAILY_SALARY * 0.75)

    if day >= 8 and hp > 5 and no_water_days == 0 and supply >= 20:
        target *= 0.9

    cap = budget
    if budget < DAILY_SALARY * 0.5 and danger < 0.9:
        target = min(target, budget)
    else:
        target = min(target, cap)

    if target < 0:
        target = 0.0

    return float(round(min(budget, target), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = DAILY_SALARY * 0.6 

    if my_status['no_water_days'] >= 1:
        bid = DAILY_SALARY * 0.95
        if highest_prev_bid > 0:
            bid = max(bid, highest_prev_bid + 10)
    elif my_status['hp'] <= 3:
        bid = DAILY_SALARY * 0.85
        if highest_prev_bid > 0:
            bid = max(bid, highest_prev_bid + 5)
    else:
        if highest_prev_bid > 0:
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                bid = max(bid, highest_prev_bid + 2)
            else:
                bid = max(bid, highest_prev_bid + 1)
        bid = max(bid, DAILY_SALARY * 0.55)

    if day_context['day'] >= 8:
        if my_status['budget'] > DAILY_SALARY * 2:
            bid = max(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, DAILY_SALARY * 0.75)

    final_bid = min(bid, my_status['budget'])

    if final_bid <= 0 and my_status['budget'] > 0 and (my_status['no_water_days'] >= 1 or my_status['hp'] <= 3):
        final_bid = 1

    return max(0, final_bid)
